(function(root){const clone=x=>JSON.parse(JSON.stringify(x));const groups=['music_tracks','ambience_tracks','effect_tracks'],kinds={music_tracks:['bgm','song'],ambience_tracks:['ambience'],effect_tracks:['sfx','sync']};
function ranges(p){let t=0;return(p.shots||[]).map(s=>{const r={shot:s,id:s.shot_id||s.id,scene_id:s.scene_id,start:t,end:t+Number(s.duration??s.duration_seconds??0)};t=r.end;return r;});}
function global(p){return p.shotScript?.global_audio||p.global_audio||{};}
function defaultMusicPrompt(p){const comedy=/喜剧|搞笑|相亲/.test(String(p.genre||'')+' '+String(p.title||''));return comedy?'Warm light rural comedy instrumental background score, gentle plucked acoustic strings, soft woodwind and light percussion, playful but restrained, 80 BPM. Low dynamics and a sparse arrangement leave clear space for Mandarin dialogue. No vocals, no speech, no dramatic hits.':'Gentle cinematic instrumental background score, warm acoustic textures and soft piano, restrained steady rhythm, 80 BPM. Sparse arrangement and low dynamics leave clear space for dialogue. No vocals, no speech.';}
function ensureDefaultMusic(p,g){if(g.default_music_initialized)return;g.default_music_initialized=true;const total=ranges(p).at(-1)?.end||0;if(!total)return;let track=g.music_tracks.find(t=>(t.kind||'bgm')==='bgm');if(!track){track={track_id:'BGM_DEFAULT',name:'背景音乐',kind:'bgm',start_time_seconds:0,end_time_seconds:Number(total.toFixed(2)),volume_db:-18,fade_in_seconds:1,fade_out_seconds:2};g.music_tracks.push(track);}track.generation??={};if(!String(track.generation.prompt||track.style_prompt||'').trim()){track.generation.prompt=defaultMusicPrompt(p);track.generation.bpm??=80;track.generation.lyrics='';track.generation.duration_seconds=Math.min(180,Number(total.toFixed(2)));} }
function ensure(p){p.shotScript??={};const existing=global(p);p.shotScript.global_audio=existing;for(const g of groups)existing[g]??=[];ensureDefaultMusic(p,existing);if(existing.timeline_version==='1.0')return existing;const rs=ranges(p),total=rs.at(-1)?.end||0;for(const m of existing.music_tracks){m.kind??=m.lyrics?'song':'bgm';m.start_time_seconds??=0;m.end_time_seconds??=total;m.generation??={prompt:m.style_prompt||'',bpm:80,lyrics:m.lyrics||''};m.volume_db??=-12;m.fade_in_seconds??=.5;m.fade_out_seconds??=1;}
let last;for(const r of rs){for(const [n,c]of(r.shot.audio?.ambience||[]).entries()){const id=c.sound_id||'ROOMTONE',start=r.start+Number(c.start_offset_seconds||0),end=Math.min(r.end,r.start+Number(c.end_offset_seconds??(r.end-r.start)));if(end<=start)continue;if(last&&last._sound_id===id&&last.scene_id===r.scene_id&&Math.abs(last.end_time_seconds-start)<.03){last.end_time_seconds=end;last.shot_ids.push(r.id);}else{last={track_id:'AMB_'+String(id).replace(/[^A-Za-z0-9_-]/g,'_')+'_'+existing.ambience_tracks.length,kind:'ambience',name:c.description||id,scene_id:r.scene_id,shot_ids:[r.id],start_time_seconds:start,end_time_seconds:end,generation:{prompt:c.generation?.prompt||c.description||''},volume_db:-12,fade_in_seconds:.3,fade_out_seconds:.5,_sound_id:id};existing.ambience_tracks.push(last);}}
for(const [n,c]of(r.shot.audio?.sfx||[]).entries()){const start=Number(c.start_offset_seconds??c.at_offset_seconds??0),end=Math.min(r.end-r.start,Number(c.end_offset_seconds??(start+Math.min(2,r.end-r.start-start)))) ;if(end>start)existing.effect_tracks.push({track_id:'SFX_'+r.id+'_'+n,kind:'sfx',name:c.description||c.sound_id||'动作音效',shot_id:r.id,start_offset_seconds:start,end_offset_seconds:end,generation:{prompt:c.generation?.prompt||c.description||''},volume_db:-6,fade_in_seconds:.05,fade_out_seconds:.1});}}
for(const t of existing.ambience_tracks)delete t._sound_id;existing.timeline_version='1.0';p.audioTimelineState??={};return existing;}
function tracks(p){const g=global(p),rs=ranges(p);return groups.flatMap(group=>(g[group]||[]).map((raw,index)=>{const kind=raw.kind||(group==='music_tracks'?'bgm':group==='ambience_tracks'?'ambience':'sfx'),shot=rs.find(r=>r.id===raw.shot_id),start=group==='effect_tracks'?(shot?.start||0)+Number(raw.start_offset_seconds??0):Number(raw.start_time_seconds??0),end=group==='effect_tracks'?(shot?.start||0)+Number(raw.end_offset_seconds??0):Number(raw.end_time_seconds??0);return{...raw,group,kind,track_id:raw.track_id||'AUDIO_'+group+'_'+index,start,end,duration:end-start,prompt:raw.generation?.prompt||raw.style_prompt||raw.description||'',lyrics:raw.generation?.lyrics||raw.lyrics||'',bpm:Number(raw.generation?.bpm||80),raw};}));}
function validate(p){const ids=new Set(),rs=ranges(p),total=rs.at(-1)?.end||0;for(const t of tracks(p)){if(!/^[A-Za-z0-9_-]{1,96}$/.test(t.track_id)||ids.has(t.track_id))throw Error('音轨编号无效或重复：'+t.track_id);ids.add(t.track_id);if(!kinds[t.group].includes(t.kind))throw Error(t.track_id+' 声音类别与音轨分组不一致');if(!Number.isFinite(t.start)||!Number.isFinite(t.end)||t.start<0||t.duration<=0||t.end>total+.03)throw Error(t.track_id+' 音轨时间超出整片范围');if(t.group==='effect_tracks'){const r=rs.find(r=>r.id===t.shot_id);if(!r||Number(t.start_offset_seconds)<0||Number(t.end_offset_seconds)>r.end-r.start+.03)throw Error(t.track_id+' 动作音效超出所属分镜');}if(t.scene_id&&!(p.scenes||[]).some(s=>(s.scene_id||s.id)===t.scene_id)&&!rs.some(r=>r.scene_id===t.scene_id))throw Error(t.track_id+' 场景不存在');}return true;}
function target(p,input){if(input.scope==='timeline'){const t=tracks(p).find(t=>t.track_id===input.track_id);if(!t||input.target_id!=='track:'+t.track_id||input.kind!==t.kind)throw Error('音轨不存在或声音类别不匹配');return t;}if(!(p.shots||[]).some(s=>(s.shot_id||s.id)===input.target_id))throw Error('分镜不存在');return null;}
function placements(p,items,t){const rs=ranges(p),parts=[];let cursor=0;for(const item of items){const r=rs.find(r=>r.id===item.target_id);if(r){const a=Math.max(r.start,t.start),b=Math.min(r.end,t.end);if(b>a){const piece={start:cursor+a-r.start,end:cursor+Math.min(item.duration,b-r.start),source:a-t.start,originalEnd:b,index:rs.indexOf(r)};if(piece.end>piece.start){const prev=parts.at(-1);if(prev&&piece.index===prev.index+1&&Math.abs(prev.originalEnd-a)<.03){prev.end=piece.end;prev.originalEnd=b;prev.index=piece.index;}else parts.push(piece);}}}cursor+=item.duration;}return parts.map(({start,end,source})=>({start,end,duration:end-start,audio_offset_seconds:source}));}
function collect(p,items,readAudio){const selected=p.audioTimelineState||{},out=[];for(const t of tracks(p)){const s=selected[t.track_id];if(!s?.enabled||!s.activeId)continue;const a=readAudio(s.activeId);if(a.project_id!==p.project_id||a.scope!=='timeline'||a.track_id!==t.track_id||a.kind!==t.kind||a.status!=='completed')throw Error('采用的音频与音轨不匹配：'+t.track_id);const volume=Number(s.volume_db??t.volume_db??(t.kind==='bgm'?-12:-6));if(!Number.isFinite(volume)||volume< -60||volume>6)throw Error('音轨音量无效');const loop=s.loop??t.loop??false;for(const part of placements(p,items,t)){const offset=Number(s.audio_offset_seconds||0)+part.audio_offset_seconds,duration=loop?part.duration:Math.min(part.duration,a.duration-offset);if(offset<0||!Number.isFinite(offset))throw Error('音频起点无效');if(duration>0)out.push({...part,end:part.start+duration,duration,audio_offset_seconds:offset,audio_id:a.id,target_id:'track:'+t.track_id,track_id:t.track_id,kind:t.kind,timeline_track:true,loop:loop===true,volume_db:volume,fade_in_seconds:Number(s.fade_in_seconds??t.fade_in_seconds??.3),fade_out_seconds:Number(s.fade_out_seconds??t.fade_out_seconds??.5)});}}
return out;}
const api={defaultMusicPrompt,ensure,global,tracks,validate,target,placements,collect,ranges};if(typeof module!=='undefined')module.exports=api;else root.AudioTimeline=api;
})(typeof window==='undefined'?globalThis:window);
